const r = $input.first().json;
const body = r.body && typeof r.body === 'object' && !Array.isArray(r.body) ? r.body : {};
return [{ json: { triggered_by: 'manual', force: body.force === true, headers: r.headers || {} } }];

// ============================================================================
// MONITOR RULES: the node for what is special about YOUR workflows. DATA ONLY (no logic).
// Edit the values between the EDIT lines. Every cycle checks them first; a mistake gives a clear
// "monitor_misconfigured" error (lines start "Rules:") before anything is fetched, retried or sent.
// Rules can only make the monitor MORE careful (fewer retries, never retry, ignore, louder text).
// What you cannot change here, on purpose: the lock, the time window and watermark, the backoff,
// storm suppression, the alert cooldown, the recovery check, and the CONFIG retry ceiling.
// ============================================================================
// ---- EDIT FROM HERE ---------------------------------------------------------
const rules = {
  // Workflows the monitor leaves alone completely. Match by id or by a name pattern (one key per entry).
  // Example: [{ id: 'abc123' }, { name_regex: '^Test: ' }]
  ignore_workflows: [],
  // Per-workflow handling. The first entry that matches wins. Match with id OR name_regex, then any of:
  //   max_retries (a whole number, never above CONFIG.MAX_RETRIES), auto_retry: false (never retry, page a person),
  //   alert_prefix (text put in front of the alert title, e.g. ':rotating_light: P1'), note (a line added to the alert).
  // Example: [{ name_regex: 'Payments', max_retries: 1, alert_prefix: ':rotating_light: P1', note: 'Owner: Dana' }]
  workflow_overrides: [],
  // Failures at nodes whose name matches are never auto-retried (use for steps that are not safe to repeat, such as
  // charging a card). They page a person instead. Example: ['^Charge Card', 'Send Invoice']
  never_retry_nodes: [],
  // Wording of the "needs attention" alert.
  alert: {
    title: 'Workflow needs attention',
    icon: ':warning:',
    // Which lines to show, in order. Choose from: workflow, node, reason, error, executions. workflow and reason are required.
    fields: ['workflow', 'node', 'reason', 'error', 'executions'],
    // One extra line at the end of every alert, e.g. 'Runbook: https://wiki.example.com/n8n-oncall'.
    extra_line: '',
    // Replace the wording for a reason. Keys: permanent_error, unknown_error, retries_exhausted, retry_dispatch_failed,
    // auto_retry_disabled, retry_blocked_by_rules.
    reasons: {},
  },
};
// ---- STOP EDITING HERE ------------------------------------------------------
const pick = (o, k, d) => (o && o[k] !== undefined && o[k] !== null ? o[k] : d);
const A = pick(rules, 'alert', {});
const norm = { ignore_workflows: pick(rules, 'ignore_workflows', []), workflow_overrides: pick(rules, 'workflow_overrides', []), never_retry_nodes: pick(rules, 'never_retry_nodes', []),
  alert: { title: pick(A, 'title', 'Workflow needs attention'), icon: pick(A, 'icon', ':warning:'), fields: pick(A, 'fields', ['workflow', 'node', 'reason', 'error', 'executions']),
    extra_line: pick(A, 'extra_line', ''), reasons: pick(A, 'reasons', {}) },
  _is_obj: rules !== null && typeof rules === 'object' && !Array.isArray(rules), _alert_is_obj: A !== null && typeof A === 'object' && !Array.isArray(A),
  _raw_keys: Object.keys(rules || {}), _alert_keys: Object.keys(A || {}) };
return [{ json: { ...$input.first().json, rules: norm } }];

const C = $('CONFIG').first().json;
const r = $input.first().json;
const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const reject = (status, error, details) => [{ json: { ok: false, triggered_by: r.triggered_by, http_status: status, response_body: { error, ...(details ? { details } : {}) } } }];

if (r.triggered_by === 'manual' && C.MONITOR_AUTH_TOKEN && (r.headers || {})['x-monitor-token'] !== C.MONITOR_AUTH_TOKEN) return reject(401, 'unauthorized');

const bad = [];
for (const k of ['N8N_API_URL', 'MONITOR_STATE_API_URL']) if (!/^https?:\/\//.test(C[k] || '')) bad.push(`CONFIG.${k} must start with http:// or https://`);
if (!String(C.N8N_API_KEY || '').trim()) bad.push('CONFIG.N8N_API_KEY is empty (create an API key in n8n: Settings > n8n API)');
if (C.SLACK_WEBHOOK_URL && !/^https?:\/\//.test(C.SLACK_WEBHOOK_URL)) bad.push('CONFIG.SLACK_WEBHOOK_URL must be blank or start with http(s)://');
try { if (!isObj(JSON.parse(C.MONITOR_STATE_HEADERS_JSON || '{}'))) throw 0; } catch (e) { bad.push('CONFIG.MONITOR_STATE_HEADERS_JSON must be a JSON object'); }
for (const k of ['TRANSIENT_PATTERNS_JSON', 'PERMANENT_PATTERNS_JSON']) {
  try { const a = JSON.parse(C[k]); if (!Array.isArray(a)) throw 0; a.forEach((p) => new RegExp(p, 'i')); } catch (e) { bad.push(`CONFIG.${k} must be a JSON array of valid regular expressions`); }
}
for (const k of ['LOCK_TTL_SECONDS', 'BOOTSTRAP_LOOKBACK_MINUTES', 'PAGE_SIZE', 'MAX_PAGES', 'MAX_EXECUTIONS_PER_CYCLE', 'STORM_THRESHOLD', 'MAX_RETRIES',
  'BACKOFF_BASE_MINUTES', 'BACKOFF_MULTIPLIER', 'ALERT_COOLDOWN_MINUTES', 'MAX_RETRIES_PER_INCIDENT_PER_CYCLE', 'REQUEST_TIMEOUT_MS'])
  if (!(Number(C[k]) > 0)) bad.push(`CONFIG.${k} must be a number > 0`);
if (!(Number(C.BACKOFF_JITTER_SECONDS) >= 0)) bad.push('CONFIG.BACKOFF_JITTER_SECONDS must be a number >= 0');
// ---- the Monitor Rules node
{
  const R = $('Monitor Rules').first().json.rules;
  const rb = (m) => bad.push('Rules: ' + m);
  const str = (x, max) => typeof x === 'string' && x.length > 0 && x.length <= max && !/[\r\n]/.test(x);
  const rx = (x) => { if (!str(x, 200)) return false; try { new RegExp(x, 'i'); return true; } catch (e) { return false; } };
  const list = (v, max, f) => Array.isArray(v) && v.length <= max && v.every(f);
  const matchOk = (o, extra) => isObj(o) && Object.keys(o).every((k) => ['id', 'name_regex', ...extra].includes(k)) && ((o.id !== undefined) !== (o.name_regex !== undefined))
    && (o.id === undefined || str(o.id, 100)) && (o.name_regex === undefined || rx(o.name_regex));
  const REASONS = ['permanent_error', 'unknown_error', 'retries_exhausted', 'retry_dispatch_failed', 'auto_retry_disabled', 'retry_blocked_by_rules'];
  if (!R._is_obj) rb('rules must be an object');
  else {
    for (const k of R._raw_keys) if (!['ignore_workflows', 'workflow_overrides', 'never_retry_nodes', 'alert'].includes(k)) rb(`${k} is not a known setting (ignore_workflows, workflow_overrides, never_retry_nodes, alert)`);
    if (!list(R.ignore_workflows, 100, (o) => matchOk(o, []))) rb('ignore_workflows must be a list of at most 100 entries, each with exactly one of id (text) or name_regex (a valid pattern)');
    const ovOk = (o) => matchOk(o, ['max_retries', 'auto_retry', 'alert_prefix', 'note'])
      && (o.max_retries === undefined || (Number.isInteger(o.max_retries) && o.max_retries >= 1 && o.max_retries <= Number(C.MAX_RETRIES)))
      && (o.auto_retry === undefined || o.auto_retry === false)
      && (o.alert_prefix === undefined || str(o.alert_prefix, 100)) && (o.note === undefined || str(o.note, 300))
      && ['max_retries', 'auto_retry', 'alert_prefix', 'note'].some((k) => o[k] !== undefined);
    if (!list(R.workflow_overrides, 100, ovOk)) rb(`workflow_overrides must be a list of at most 100 entries: exactly one of id or name_regex, plus at least one of max_retries (whole number from 1 to CONFIG.MAX_RETRIES = ${C.MAX_RETRIES}), auto_retry (only false), alert_prefix (text, 100 max), note (text, 300 max)`);
    if (!list(R.never_retry_nodes, 50, rx)) rb('never_retry_nodes must be a list of at most 50 valid patterns (text)');
    if (!R._alert_is_obj) rb('alert must be an object');
    else {
      for (const k of R._alert_keys) if (!['title', 'icon', 'fields', 'extra_line', 'reasons'].includes(k)) rb(`alert.${k} is not a known setting (title, icon, fields, extra_line, reasons)`);
      const A = R.alert;
      if (!str(A.title, 100)) rb('alert.title must be text (1 to 100 characters, one line)');
      if (!(typeof A.icon === 'string' && A.icon.length <= 50 && !/[\r\n]/.test(A.icon))) rb('alert.icon must be one line of text, 50 characters at most (it may be empty)');
      if (!(Array.isArray(A.fields) && new Set(A.fields).size === A.fields.length && A.fields.every((f) => ['workflow', 'node', 'reason', 'error', 'executions'].includes(f)) && A.fields.includes('workflow') && A.fields.includes('reason'))) rb('alert.fields must be a list of different names from workflow, node, reason, error, executions, and must include workflow and reason');
      if (!(typeof A.extra_line === 'string' && A.extra_line.length <= 300 && !/[\r\n]/.test(A.extra_line))) rb('alert.extra_line must be one line of text, 300 characters at most');
      if (!isObj(A.reasons) || Object.entries(A.reasons).some(([k, v]) => !REASONS.includes(k) || !str(v, 300))) rb(`alert.reasons must be an object whose names are from ${REASONS.join(', ')} and whose values are one line of text (300 max)`);
    }
  }
}
if (bad.length) return reject(500, 'monitor_misconfigured', bad);
return [{ json: { ok: true, triggered_by: r.triggered_by, force: r.force, now: Date.now() } }];

const ctx = $('Validate Trigger').first().json;
const r = $input.first().json;
const body = r.body && typeof r.body === 'object' ? r.body : {};
const base = { triggered_by: ctx.triggered_by, force: ctx.force, now: ctx.now };
if (r.error || typeof r.statusCode !== 'number' || r.statusCode < 200 || r.statusCode >= 300)
  return [{ json: { ...base, route: 'degraded', degraded_reason: 'state_service_unavailable', degraded_detail: r.error ? String(r.error.message || r.error).slice(0, 200) : `lock call returned status ${r.statusCode}` } }];
if (body.acquired === true) return [{ json: { ...base, route: 'proceed', lock_token: body.token || null, forced_through: false } }];
if (ctx.force) return [{ json: { ...base, route: 'proceed', lock_token: null, forced_through: true } }];
return [{ json: { ...base, route: 'skip', lock_token: null } }];

const C = $('CONFIG').first().json;
const ctx = $('Evaluate Lock').first().json;
const r = $input.first().json;
if (r.error || typeof r.statusCode !== 'number' || (r.statusCode >= 300 && r.statusCode !== 404) || r.statusCode < 200 && r.statusCode !== 404)
  return [{ json: { ok: false, degraded_reason: 'state_service_unavailable', degraded_detail: r.error ? String(r.error.message || r.error).slice(0, 200) : `last-checked returned status ${r.statusCode}` } }];
const body = r.statusCode === 404 ? {} : (r.body || {});
const last = Number(body.last_checked_at);
let since = Number.isFinite(last) && last > 0 ? last : ctx.now - Number(C.BOOTSTRAP_LOOKBACK_MINUTES) * 60000;
if (since > ctx.now) since = ctx.now - Number(C.BOOTSTRAP_LOOKBACK_MINUTES) * 60000;   // clock moved backwards: do not skip the future
return [{ json: { ok: true, since, until: ctx.now, cursor: null, bootstrapped: !(Number.isFinite(last) && last > 0) } }];

const C = $('CONFIG').first().json;
const win = $('Compute Poll Window').first().json;
const r = $input.first().json;
const pageNo = $runIndex + 1;
const ok = !r.error && typeof r.statusCode === 'number' && r.statusCode >= 200 && r.statusCode < 300 && r.body && Array.isArray(r.body.data);
if (!ok) return [{ json: { page_ok: false, more: false, degraded_reason: 'n8n_api_unavailable',
  degraded_detail: r.error ? String(r.error.message || r.error).slice(0, 200) : `n8n API returned status ${r.statusCode}` } }];

const ts = (e) => Date.parse(e.stoppedAt || e.startedAt || '') || 0;
let all = [];
for (let i = 0; i <= $runIndex; i++) all = all.concat((($('Fetch Failed Executions Page').first(0, i).json.body || {}).data) || []);
const page = r.body.data;
const oldest = page.length ? ts(page[page.length - 1]) : 0;
const nextCursor = r.body.nextCursor || null;
const windowCovered = page.length === 0 || oldest < win.since;        // newest-first: once a page reaches before `since`, older pages are irrelevant
const hitCap = !!nextCursor && !windowCovered && pageNo >= Number(C.MAX_PAGES);
const more = !!nextCursor && !windowCovered && pageNo < Number(C.MAX_PAGES);

const selfId = $workflow.id;
const executions = all.filter((e) => {
  const t = ts(e);
  if (!(t >= win.since && t < win.until)) return false;
  if (e.retrySuccessId) return false;                                        // already retried successfully
  if (e.workflowId === selfId) return false;                                 // the monitor does not monitor itself (use n8n's Error Workflow for that)
  if (C.IGNORE_MANUAL_EXECUTIONS && e.mode === 'manual') return false;       // test runs from the editor
  return true;
});
return [{ json: { page_ok: true, more, next_cursor: nextCursor, pages_fetched: pageNo, truncated_pages: hitCap, executions } }];

const C = $('CONFIG').first().json;
const t = $input.first().json;
if (!t.page_ok) return [{ json: { page_ok: false, degraded_reason: t.degraded_reason, degraded_detail: t.degraded_detail } }];
const execs = t.executions;
const distinct = new Set(execs.map((e) => e.workflowId));
return [{ json: { page_ok: true, executions: execs, total_failed: execs.length, distinct_workflow_count: distinct.size,
  is_storm: distinct.size >= Number(C.STORM_THRESHOLD), truncated_pages: t.truncated_pages, pages_fetched: t.pages_fetched } }];

const C = $('CONFIG').first().json;
const a = $('Assess Failure Batch').first().json;
const r = $input.first().json;
const last = r.statusCode >= 200 && r.statusCode < 300 && r.body ? Number(r.body.last_alerted_at) || 0 : 0;
const due = !!C.SLACK_WEBHOOK_URL && (Date.now() - last >= Number(C.ALERT_COOLDOWN_MINUTES) * 60000);
return [{ json: { due, text: `:fire: *Failure storm detected* -- ${a.distinct_workflow_count} different workflows failed in the last poll window (${a.total_failed} executions). Suppressing individual auto-retries to avoid piling onto what is probably one shared outage. Investigate before the next cycle.` } }];

const C = $('CONFIG').first().json;
const a = $('Assess Failure Batch').first().json;
const cap = Number(C.MAX_EXECUTIONS_PER_CYCLE);
return a.executions.slice(0, cap).map((e) => ({ json: { execution_id: String(e.id), workflow_id: e.workflowId, stopped_at: e.stoppedAt || e.startedAt, mode: e.mode } }));

const C = $('CONFIG').first().json;
const T = JSON.parse(C.TRANSIENT_PATTERNS_JSON).map((p) => new RegExp(p, 'i'));
const P = JSON.parse(C.PERMANENT_PATTERNS_JSON).map((p) => new RegExp(p, 'i'));
const NR = $('Monitor Rules').first().json.rules.never_retry_nodes.map((p) => new RegExp(p, 'i'));
const out = [];
$input.all().forEach((it, i) => {
  const src = $('Split Into Per-Execution Items').itemMatching(i).json;
  const d = it.json;
  const ok = !d.error && d.statusCode >= 200 && d.statusCode < 300 && d.body;
  const rd = ok && d.body.data && d.body.data.resultData ? d.body.data.resultData : {};
  const err = rd.error || {};
  const message = String(err.message || err.description || '');
  const text = [message, err.description, err.httpCode].filter((x) => x !== undefined && x !== null).join(' ');
  const code = Number(err.httpCode);
  let failure_type = 'unknown';
  if (Number.isFinite(code) && (code >= 500 || code === 429 || code === 408)) failure_type = 'transient';
  else if (Number.isFinite(code) && code >= 400 && code < 500) failure_type = 'permanent';
  else if (T.some((re) => re.test(text))) failure_type = 'transient';
  else if (P.some((re) => re.test(text))) failure_type = 'permanent';
  const failed_node = rd.lastNodeExecuted || (err.node && err.node.name) || 'unknown';
  let rules_blocked = false;
  if (failure_type === 'transient' && NR.some((re) => re.test(failed_node))) { failure_type = 'unknown'; rules_blocked = true; }   // Monitor Rules: not safe to repeat -> a person decides
  out.push({ json: { ...src, failed_node, error_message: message.slice(0, 500),
    failure_type, rules_blocked, detail_ok: !!ok } });
});
return out;

const A = $('Assess Failure Batch').first().json;
const fnv = (s) => { let h = 0x811c9dc5; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; } return h.toString(16).padStart(8, '0'); };
const slug = (s) => String(s).replace(/[^A-Za-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 40) || 'x';
const groups = new Map();
for (const it of $input.all()) {
  const t = it.json;
  const raw = `${t.workflow_id}::${t.failed_node}::${t.failure_type}` + (t.rules_blocked ? '::blocked' : '');
  const key = `${slug(t.workflow_id)}.${slug(t.failed_node)}.${t.failure_type}.${fnv(raw)}`;
  if (!groups.has(key)) groups.set(key, { incident_key: key, workflow_id: t.workflow_id, failed_node: t.failed_node, failure_type: t.failure_type, rules_blocked: !!t.rules_blocked, executions: [] });
  groups.get(key).executions.push(t);
}
return [...groups.values()].map((g) => {
  g.executions.sort((a, b) => (Date.parse(b.stopped_at) || 0) - (Date.parse(a.stopped_at) || 0));
  const newest = g.executions[0];
  return { json: { incident_key: g.incident_key, workflow_id: g.workflow_id, failed_node: g.failed_node, failure_type: g.failure_type, rules_blocked: g.rules_blocked,
    error_message: newest.error_message, execution_ids: g.executions.map((x) => x.execution_id), failure_count: g.executions.length,
    last_failure_at: Date.parse(newest.stopped_at) || Date.now(), is_storm: A.is_storm } };
});

const R = $('Monitor Rules').first().json.rules;
return $input.all().map((it, i) => {
  const g = $('Group Into Incidents').itemMatching(i).json;
  const r = it.json;
  const found = !r.error && r.statusCode >= 200 && r.statusCode < 300 && r.body;
  const deleted = !r.error && r.statusCode === 404;
  const active = found ? r.body.active === true : true;       // could not check: do not silently drop a real failure
  const workflow_name = found && r.body.name ? r.body.name : g.workflow_id;
  const ignored = R.ignore_workflows.some((m) => (m.id !== undefined && m.id === g.workflow_id) || (m.name_regex !== undefined && new RegExp(m.name_regex, 'i').test(workflow_name)));   // Monitor Rules
  return { json: { ...g, workflow_name, workflow_active: active,
    process: !deleted && active && !ignored, skip_reason: deleted ? 'workflow_deleted' : (!active ? 'workflow_inactive' : (ignored ? 'ignored_by_rules' : null)) } };
});

const C = $('CONFIG').first().json;
const R = $('Monitor Rules').first().json.rules;
const now = Date.now();
return $input.all().map((it, i) => {
  const g = $('Evaluate Workflow').itemMatching(i).json;
  const ov = R.workflow_overrides.find((m) => (m.id !== undefined && m.id === g.workflow_id) || (m.name_regex !== undefined && new RegExp(m.name_regex, 'i').test(g.workflow_name))) || {};
  const maxRetries = ov.max_retries !== undefined ? Math.min(Number(C.MAX_RETRIES), ov.max_retries) : Number(C.MAX_RETRIES);   // a rule can only lower the ceiling
  const r = it.json;
  const stateOk = !r.error && typeof r.statusCode === 'number' && ((r.statusCode >= 200 && r.statusCode < 300) || r.statusCode === 404);
  let state = stateOk && r.statusCode !== 404 ? (r.body || {}) : null;
  if (state && state.status === 'resolved') state = null;                 // a resolved incident that fails again is a new incident
  const retries_used = Number(state && state.retries_used) || 0;
  const next_retry_at = Number(state && state.next_retry_at) || 0;
  const last_alerted_at = Number(state && state.last_alerted_at) || 0;
  let action, escalate_reason = null;
  if (!stateOk) action = 'state_error';
  else if (g.is_storm) action = 'suppress_storm';
  else if (g.failure_type === 'permanent') { action = 'escalate'; escalate_reason = 'permanent_error'; }
  else if (g.failure_type === 'unknown') { action = 'escalate'; escalate_reason = g.rules_blocked ? 'retry_blocked_by_rules' : 'unknown_error'; }
  else if (ov.auto_retry === false) { action = 'escalate'; escalate_reason = 'auto_retry_disabled'; }
  else if (retries_used >= maxRetries) { action = 'escalate'; escalate_reason = 'retries_exhausted'; }
  else if (now < next_retry_at) action = 'wait_backoff';
  else action = 'retry';
  return { json: { ...g, is_new_incident: !state, retries_used, next_retry_at, last_alerted_at, action, escalate_reason, rule_alert_prefix: ov.alert_prefix || null, rule_note: ov.note || null } };
});

const C = $('CONFIG').first().json;
const cap = Number(C.MAX_RETRIES_PER_INCIDENT_PER_CYCLE);
const out = [];
for (const it of $input.all()) {
  const g = it.json;
  g.execution_ids.slice(0, cap).forEach((id) => out.push({ json: { ...g, execution_id: id } }));
}
return out;

const byKey = new Map();
$input.all().forEach((it, i) => {
  const src = $('Expand To Executions').itemMatching(i).json;
  const r = it.json;
  const ok = !r.error && r.statusCode >= 200 && r.statusCode < 300;
  if (!byKey.has(src.incident_key)) { const { execution_id, ...rest } = src; byKey.set(src.incident_key, { ...rest, dispatched: 0, dispatch_failed: 0, dispatch_error: null }); }
  const g = byKey.get(src.incident_key);
  if (ok) g.dispatched += 1; else { g.dispatch_failed += 1; g.dispatch_error = r.error ? String(r.error.message || r.error).slice(0, 200) : `retry returned status ${r.statusCode}`; }
});
return [...byKey.values()].map((g) => ({ json: { ...g, retry_ok: g.dispatched > 0, escalate_reason: g.dispatched > 0 ? null : 'retry_dispatch_failed' } }));

const C = $('CONFIG').first().json;
return $input.all().map((it) => {
  const g = it.json;
  const retries_used = g.retries_used + 1;
  const backoff = Number(C.BACKOFF_BASE_MINUTES) * 60000 * Math.pow(Number(C.BACKOFF_MULTIPLIER), retries_used - 1);
  const jitter = Math.floor(Math.random() * Number(C.BACKOFF_JITTER_SECONDS) * 1000);
  return { json: { ...g, retries_used, next_retry_at: Date.now() + backoff + jitter } };
});

return $input.all().map((it, i) => {
  const g = $('Compute Backoff').itemMatching(i).json;
  const r = it.json;
  const wrote = !r.error && r.statusCode >= 200 && r.statusCode < 300;
  return { json: { incident_key: g.incident_key, workflow_id: g.workflow_id, outcome: 'retried', executions_retried: g.dispatched, retries_used: g.retries_used, state_write_failed: !wrote } };
});

return $input.all().map((it, i) => {
  const g = $('In Alert Cooldown?').itemMatching(i).json;
  return { json: { incident_key: g.incident_key, workflow_id: g.workflow_id, outcome: 'escalation_suppressed_cooldown', escalate_reason: g.escalate_reason, state_write_failed: !!it.json.error || !(it.json.statusCode >= 200 && it.json.statusCode < 300) } };
});

const C = $('CONFIG').first().json;
const R = $('Monitor Rules').first().json.rules;
const REASON = { permanent_error: 'a permanent error (looks like a code or config bug, not transient)',
  unknown_error: 'an unrecognized failure type (needs eyes, not blind auto-retry)',
  retries_exhausted: 'retries exhausted (still failing after the automatic attempts)',
  retry_dispatch_failed: 'the automatic retry call itself failed to dispatch',
  auto_retry_disabled: 'automatic retry is switched off for this workflow (Monitor Rules)',
  retry_blocked_by_rules: 'this node is marked as not safe to repeat automatically (Monitor Rules)',
  ...R.alert.reasons };
return $input.all().map((it) => {
  const t = it.json;
  const F = { workflow: `*Workflow:* ${t.workflow_name} (${t.workflow_id})`, node: `*Failed node:* ${t.failed_node}`, reason: `*Reason:* ${REASON[t.escalate_reason] || t.escalate_reason}`,
    error: `*Error:* ${t.error_message}`, executions: `*Failed executions:* ${t.failure_count} (latest: ${t.execution_ids[0]})` };
  const head = [t.rule_alert_prefix, R.alert.icon, `*${R.alert.title}*`].filter(Boolean).join(' ');
  const lines = [head, ...R.alert.fields.map((f) => F[f]), ...(t.rule_note ? [`*Note:* ${t.rule_note}`] : []), ...(R.alert.extra_line ? [R.alert.extra_line] : [])];
  return { json: { ...t, text: lines.join('\n'), slack_configured: !!C.SLACK_WEBHOOK_URL } };
});

return $input.all().map((it, i) => {
  const t = $('Build Alert').itemMatching(i).json;
  const r = it.json;
  const skipped = r.slack_configured === false;                            // no webhook configured: alert lives in the digest only
  const sent = !skipped && !r.error && r.statusCode >= 200 && r.statusCode < 300;
  return { json: { ...t, alert_sent: sent, alert_skipped: skipped, record_alerted: skipped || sent } };   // a FAILED Slack post must not start the cooldown, or the page is lost
});

return $input.all().map((it, i) => {
  const g = $('Evaluate Alert Result').itemMatching(i).json;
  return { json: { incident_key: g.incident_key, workflow_id: g.workflow_id, outcome: 'escalated', escalate_reason: g.escalate_reason, alert_sent: g.alert_sent, alert_skipped: g.alert_skipped,
    state_write_failed: !!it.json.error || !(it.json.statusCode >= 200 && it.json.statusCode < 300) } };
});

const counts = { retried: 0, escalated: 0, escalation_suppressed_cooldown: 0, waiting_backoff: 0, suppressed_storm: 0, skipped: 0, state_error: 0 };
const items = $input.all().map((i) => i.json).filter((o) => o.outcome && o.outcome !== 'none');
let state_write_failures = 0;
for (const o of items) { if (counts[o.outcome] !== undefined) counts[o.outcome]++; if (o.state_write_failed) state_write_failures++; }
return [{ json: { outcomes: items, counts, state_write_failures } }];

const r = $input.first().json;
const ok = !r.error && r.statusCode >= 200 && r.statusCode < 300 && r.body;
const list = ok && Array.isArray(r.body.incidents) ? r.body.incidents.filter((i) => i.workflow_id && i.status === 'open') : [];
return [{ json: { recovery_ok: !!ok, candidates: list } }];

return $input.all().map((it, i) => {
  const inc = $('Split Open Incidents').itemMatching(i).json;
  const r = it.json;
  const ok = !r.error && r.statusCode >= 200 && r.statusCode < 300 && r.body && Array.isArray(r.body.data);
  const newest = ok && r.body.data.length ? r.body.data[0] : null;
  const since = Number(inc.last_failure_at) || Number(inc.opened_at) || 0;
  const t = newest ? (Date.parse(newest.startedAt || newest.stoppedAt || '') || 0) : 0;
  return { json: { ...inc, check_ok: !!ok, recovered: !!newest && t > since } };
});

const C = $('CONFIG').first().json;
return $input.all().map((it, i) => {
  const t = $('Recovered?').itemMatching(i).json;
  const r = it.json;
  const resolved = !r.error && r.statusCode >= 200 && r.statusCode < 300;
  const text = `:white_check_mark: *Recovered* -- ${t.workflow_name || t.workflow_id} is succeeding again (was failing at node ${t.failed_node}). Incident resolved.`;
  return { json: { ...t, resolved, text, send_notice: resolved && !!C.SLACK_WEBHOOK_URL } };
});

return $input.all().map((it, i) => {
  const t = $('Build Recovery Message').itemMatching(i).json;
  return { json: { incident_key: t.incident_key, workflow_id: t.workflow_id, outcome: t.resolved ? 'recovered' : 'recovery_failed' } };
});

const items = $input.all().map((i) => i.json).filter((o) => o.outcome && o.outcome !== 'none');
return [{ json: { recovered: items.filter((o) => o.outcome === 'recovered').map((o) => o.workflow_id),
  still_open_count: items.filter((o) => o.outcome === 'still_open').length,
  recovery_issues: items.filter((o) => o.outcome === 'recovery_failed' || o.outcome === 'recovery_check_failed').length } }];

const C = $('CONFIG').first().json;
const ctx = $('Validate Trigger').first().json;
const lock = $('Evaluate Lock').first().json;
const win = $('Compute Poll Window').first().json;
const out = $('Collect Outcomes').first().json;
const rec = $('Collect Recovery').first().json;
const batch = $('Assess Failure Batch').first().json;
const warnings = [];
if (batch.truncated_pages) warnings.push(`failure list hit MAX_PAGES (${C.MAX_PAGES}); older failures in this window were not examined`);
if (out.counts.state_error) warnings.push(`${out.counts.state_error} incident(s) skipped because the state service could not be read`);
if (out.state_write_failures) warnings.push(`${out.state_write_failures} incident state write(s) failed`);
if (rec.recovery_issues) warnings.push(`${rec.recovery_issues} recovery check(s) failed`);
const clean = !out.counts.state_error && !out.state_write_failures;
const alertCooldownMs = Number(C.ALERT_COOLDOWN_MINUTES) * 60000;
let alert_text = null; const alert_key = 'completed_with_warnings';
if (warnings.length) {
  const sd = $getWorkflowStaticData('global'); sd.cycle_alerts = sd.cycle_alerts || {};
  if (Date.now() - (sd.cycle_alerts[alert_key] || 0) >= alertCooldownMs) alert_text = ':warning: Self-healing monitor finished a cycle with problems: ' + warnings.join('; ') + '.';
}
const body = { status: clean ? 'completed' : 'completed_with_errors', triggered_by: ctx.triggered_by, forced_through: !!lock.forced_through,
  window: { since: new Date(win.since).toISOString(), until: new Date(win.until).toISOString(), bootstrapped: win.bootstrapped },
  failed_executions_seen: batch.total_failed, distinct_workflows_failing: batch.distinct_workflow_count, storm: batch.is_storm,
  counts: out.counts, recovered: rec.recovered, still_open_count: rec.still_open_count, warnings, watermark_advanced: clean, checked_at: new Date().toISOString() };
return [{ json: { kind: 'completed', triggered_by: ctx.triggered_by, lock_token: lock.lock_token || null, advance_watermark: clean, watermark_value: win.until,
  alert_text, alert_key, http_status: 200, response_body: body } }];

const C = $('CONFIG').first().json;
const t = $input.first().json;
const ctx = $('Validate Trigger').first().json;
let lock = null; try { lock = $('Evaluate Lock').first().json; } catch (e) { /* not reached */ }
const reason = t.degraded_reason || 'unknown';
const detail = t.degraded_detail || '';
const TEXT = {
  state_service_unavailable: `:rotating_light: Self-healing monitor cannot reach its state service (${detail}). NOTHING is being monitored until it is back.`,
  n8n_api_unavailable: `:rotating_light: Self-healing monitor could not read the n8n API (${detail}). This cycle is skipped and the watermark is not advanced, so the next cycle re-checks the same window.`,
};
const sd = $getWorkflowStaticData('global'); sd.cycle_alerts = sd.cycle_alerts || {};
let alert_text = null;
if (Date.now() - (sd.cycle_alerts[reason] || 0) >= Number(C.ALERT_COOLDOWN_MINUTES) * 60000) alert_text = TEXT[reason] || `:rotating_light: Self-healing monitor degraded: ${reason}`;
return [{ json: { kind: 'degraded', triggered_by: ctx.triggered_by, lock_token: lock ? (lock.lock_token || null) : null, advance_watermark: false, alert_text, alert_key: reason,
  http_status: 503, response_body: { status: 'monitor_degraded', reason, detail, triggered_by: ctx.triggered_by, watermark_advanced: false } } }];

const ctx = $input.first().json;
return [{ json: { kind: 'skipped', triggered_by: ctx.triggered_by, lock_token: null, advance_watermark: false, alert_text: null,
  http_status: 200, response_body: { status: 'skipped', reason: 'poll_already_in_progress', triggered_by: ctx.triggered_by } } }];

const o = $('Cycle Outcome').first().json;
const r = $input.first().json;
if (!r.error && r.statusCode >= 200 && r.statusCode < 300) {          // only a delivered alert starts the cooldown
  const sd = $getWorkflowStaticData('global'); sd.cycle_alerts = sd.cycle_alerts || {};
  sd.cycle_alerts[o.alert_key] = Date.now();
}
return [{ json: o }];
